package macro;
import star.common.*;import star.base.report.*;import java.nio.file.*;import java.util.*;
public class AuditMiniResiduals extends StarMacro {public void execute(){Simulation s=getActiveSimulation();Path r=Paths.get(s.getSessionPath()).getParent();try{StringBuilder a=new StringBuilder("{\"iteration\":"+s.getSimulationIterator().getCurrentIteration()+",\"solver_steps\":0,\"monitors\":[");int n=0;for(Monitor mon:s.getMonitorManager().getObjects())if(mon instanceof ResidualMonitor){ResidualMonitor m=(ResidualMonitor)mon;double[] y=m.getAllYValues();double peak=0;for(int k=0;k<Math.min(10,y.length);k++)peak=Math.max(peak,Math.abs(y[k]));if(n++>0)a.append(",");a.append("{\"name\":\""+m.getPresentationName()+"\",\"native_normalized\":"+m.isNormalized()+",\"normalization_type\":\""+m.getNormalizationType().getClass().getSimpleName()+"\",\"normalization_factor\":"+m.getNormalizationType().getNormalizationFactor()+",\"first\":"+y[0]+",\"initial10_peak\":"+peak+",\"last\":"+y[y.length-1]+",\"last_over_first\":"+(y[y.length-1]/Math.abs(y[0]))+"}");}a.append("]}");Files.writeString(r.resolve("RESIDUAL_NATIVE_AUDIT.json"),a.toString());Files.writeString(r.resolve("SOLVE_STATUS.json"),"{\"status\":\"AUDIT_COMPLETE\",\"solver_steps\":0,\"scientific_approved\":false}");}catch(Exception e){throw new RuntimeException(e);}}}
